import {
  WEAR_FORMS,
  wearForms,
  EQUIPMENT_CATEGORIES,
  PIERCING_LOCATIONS,
  effectiveBodySlots,
} from "../rules/equipment-classification";
import {
  BODY_SLOTS,
  allowedBodySlots,
  TECHNICAL_SLOTS,
  slotProfileErrors,
} from "../rules/equipment-slots";
import { saveEquipmentProfile } from "../services/inventory";
import { PHYSICAL_ITEM_TYPES } from "../data/item-defaults";

const GROUPS: Record<
  string,
  { title: string; labels: Record<string, string> }
> = {
  sizes: {
    title: "Tailles compatibles",
    labels: {
      tiny: "Très petit",
      small: "Petit",
      medium: "Moyen",
      large: "Grand",
      huge: "Très grand",
      gargantuan: "Gigantesque",
    },
  },
  natures: {
    title: "Natures corporelles compatibles",
    labels: {
      biological: "Biologique",
      synthetic: "Synthétique",
      hybrid: "Hybride",
      energetic: "Énergétique",
      atypical: "Atypique",
    },
  },
  hostTypes: {
    title: "Types d’hôte autorisés pour l’installation",
    labels: Object.fromEntries(PHYSICAL_ITEM_TYPES.map((type) => [type, type])),
  },
  bodySlots: {
    title: "Emplacements corporels occupés simultanément",
    labels: BODY_SLOTS,
  },
};

export function equipmentProfileGroups(
  profile: Record<string, any>,
  localize = (value: string) => value,
  itemType = "armor",
) {
  return Object.entries(GROUPS).map(([key, { title, labels: groupLabels }]) => {
    const labels =
      key === "bodySlots" ? allowedBodySlots(itemType) : groupLabels;
    const selected: string[] = Array.isArray(profile[key]) ? profile[key] : [];
    return {
      key,
      isBodySlots: key === "bodySlots",
      hiddenAttribute: key === "bodySlots" ? "hidden" : "",
      title,
      count: selected.length,
      emptyLabel:
        key === "bodySlots"
          ? "Aucun emplacement corporel déclaré."
          : "Aucune restriction déclarée.",
      choices: [
        ...new Set([
          ...Object.keys(labels),
          ...(key === "bodySlots" ? [] : selected),
        ]),
      ].map((value) => ({
        value,
        groupKey: key,
        checked: selected.includes(value),
        units: profile.slotCosts?.[value] ?? 1,
        isBodySlot: key === "bodySlots",
        label:
          key === "hostTypes" && value in labels
            ? localize(`TYPES.Item.${value}`)
            : (labels[value] ?? value),
      })),
    };
  });
}

/** Read live checkbox state, never serialized attributes or truthy form strings. */
export function equipmentProfileUpdate(
  root: ParentNode,
  itemType?: string,
): Record<string, unknown> {
  const legacyConfirmation = root.querySelectorAll<HTMLInputElement>(
    "[data-legacy-slots-confirm]",
  )[0];
  if (legacyConfirmation && !legacyConfirmation.checked)
    throw new Error(
      "Confirmez le remplacement de l’ancien emplacement après avoir vérifié les choix corporels et techniques.",
    );
  const patch: Record<string, unknown> = {
    "system.physical.equipmentProfile.slotsConfigured": true,
  };
  for (const key of Object.keys(GROUPS)) {
    patch[`system.physical.equipmentProfile.${key}`] = Array.from(
      root.querySelectorAll<HTMLInputElement>(`[data-profile-list="${key}"]`),
    )
      .filter((input) => input.checked)
      .map((input) => input.value);
  }
  for (const control of root.querySelectorAll<
    HTMLInputElement | HTMLSelectElement
  >("[data-profile-field]")) {
    if (control.disabled) continue;
    const key = control.dataset.profileField;
    if (
      ![
        "family",
        "duration",
        "installable",
        "ordinaryLiquid",
        "wearForm",
        "functionalCategory",
        "piercingLocation",
        "ornamental",
        "shieldHands",
        "technology",
        "technicalSize",
        "technologyId",
        "technicalSizeId",
        "installationKind",
        "effectSummary",
        "interfaceIds",
        "compatibleFamilies",
        "compatibleSizes",
        "compatibleTechnologies",
        "compatibleInterfaces",
      ].includes(key ?? "")
    )
      continue;
    const controlValue = (control as any).value;
    patch[`system.physical.equipmentProfile.${key}`] =
      control.dataset.profileValueType === "string-set"
        ? Array.from(
            new Set(
              (controlValue instanceof Set
                ? Array.from(controlValue)
                : Array.isArray(controlValue)
                  ? controlValue
                  : []
              )
                .map(String)
                .filter(Boolean),
            ),
          )
        : control.dataset.profileValueType === "string-list"
          ? Array.from(
              new Set(
                control.value
                  .split(/[,;\n]/)
                  .map((value) => value.trim())
                  .filter(Boolean),
              ),
            )
          : control.type === "number"
            ? control.value.trim() === ""
              ? null
              : Number(control.value)
            : control.type === "checkbox"
              ? (control as HTMLInputElement).checked
              : String(controlValue ?? "").trim();
    if (key === "technologyId")
      patch["system.physical.equipmentProfile.technology"] =
        patch[`system.physical.equipmentProfile.${key}`];
    if (key === "technicalSizeId")
      patch["system.physical.equipmentProfile.technicalSize"] =
        patch[`system.physical.equipmentProfile.${key}`];
  }
  for (const field of ["requiredSlots", "providedSlots"]) {
    const controls = root.querySelectorAll<HTMLInputElement>(
      `[data-profile-technical="${field}"]`,
    );
    for (const control of controls) {
      const key = control.dataset.slotKey ?? "";
      const value = control.value.trim() === "" ? 0 : Number(control.value);
      if (
        !Object.hasOwn(TECHNICAL_SLOTS, key) ||
        !Number.isSafeInteger(value) ||
        value < 0
      )
        throw new Error(
          "Les capacités et besoins doivent être des entiers positifs ou nuls.",
        );
      patch[`system.physical.equipmentProfile.${field}.${key}`] = value;
    }
  }
  for (const control of root.querySelectorAll<HTMLInputElement>(
    "[data-profile-cost]",
  )) {
    if (control.disabled) continue;
    const key = control.dataset.profileCost ?? "";
    const units = Number(control.value);
    if (
      !Object.hasOwn(BODY_SLOTS, key) ||
      !Number.isSafeInteger(units) ||
      units < 1
    )
      throw new Error(
        "Le nombre de places occupées doit être un entier positif.",
      );
    patch[`system.physical.equipmentProfile.slotCosts.${key}`] = units;
  }
  const profile = Object.fromEntries(
    Object.entries(patch).map(([key, value]) => [
      key.slice("system.physical.equipmentProfile.".length),
      value,
    ]),
  );
  if (profile.wearForm && profile.wearForm !== "composite")
    patch["system.physical.equipmentProfile.bodySlots"] =
      effectiveBodySlots(profile);
  const errors = slotProfileErrors(profile, itemType);
  if (errors.length) throw new Error(errors.join(" "));
  return patch;
}

export function bindEquipmentProfile(
  root: HTMLElement,
  item: {
    isOwner: boolean;
    id?: string;
    type?: string;
    parent?: Actor | null;
    system?: Record<string, any>;
    update(data: Record<string, unknown>): Promise<unknown>;
  },
  reportError: (message: string) => void,
): void {
  const section = root.querySelector<HTMLElement>("[data-equipment-profile]");
  const button = section?.querySelector<HTMLButtonElement>(
    "[data-save-equipment-profile]",
  );
  if (!section || !button || !item.isOwner) return;
  if (
    item.system?.physical?.equipmentProfile?.wearForm === "composite" &&
    !game.user?.isGM
  ) {
    section
      .querySelectorAll<
        HTMLInputElement | HTMLSelectElement | HTMLButtonElement
      >("input, select, button")
      .forEach((control) => {
        control.disabled = true;
      });
    return;
  }
  const status = section.querySelector<HTMLElement>("[data-profile-status]");
  const refresh = () => {
    const selected = section.querySelector<HTMLSelectElement>(
      '[data-profile-field="wearForm"]',
    )?.value;
    section
      .querySelectorAll<HTMLElement>('[data-profile-group="bodySlots"]')
      .forEach((el) => {
        el.hidden = selected !== "composite";
      });
    section
      .querySelectorAll<HTMLElement>("[data-piercing-fields]")
      .forEach((el) => {
        el.hidden = selected !== "piercing";
      });
    section
      .querySelectorAll<HTMLElement>("[data-shield-fields]")
      .forEach((el) => {
        el.hidden = selected !== "shield";
      });
  };
  refresh();
  section.addEventListener("change", () => {
    refresh();
    if (status) status.textContent = "Modifications non enregistrées.";
  });
  button.addEventListener("click", async () => {
    if (!item.isOwner || button.disabled) return;
    button.disabled = true;
    try {
      await saveEquipmentProfile(
        item,
        equipmentProfileUpdate(section, item.type),
      );
      if (status) status.textContent = "Propriétés enregistrées.";
    } catch (error) {
      reportError(
        error instanceof Error
          ? error.message
          : "Les propriétés n’ont pas pu être enregistrées.",
      );
    } finally {
      button.disabled = !item.isOwner;
    }
  });
}

export function technicalSlotRows(profile: Record<string, any>) {
  return Object.entries(TECHNICAL_SLOTS).map(([key, label]) => ({
    key,
    label,
    required: profile.requiredSlots?.[key] ?? 0,
    provided: profile.providedSlots?.[key] ?? 0,
  }));
}

export function classificationContext(
  profile: Record<string, any>,
  type: string,
  isGM: boolean,
) {
  const forms: Record<string, string> = {
    "": "Ancien profil / à configurer",
    ...Object.fromEntries(
      Object.entries(wearForms(type)).map(([key, value]) => [key, value.label]),
    ),
  };
  if (isGM || profile.wearForm === "composite")
    forms.composite = "Profil composé — définition réservée au MJ";
  return {
    wearFormOptions: forms,
    functionalCategories: EQUIPMENT_CATEGORIES,
    piercingLocations: PIERCING_LOCATIONS,
    profileIsGM: isGM,
    profileLocked: !isGM && profile.wearForm === "composite",
    wearFormLabel:
      WEAR_FORMS[profile.wearForm]?.label ?? "Profil ancien ou composé",
  };
}
